from pathlib import Path
import re
metrics=['CSPS','AUL','AULA','CRR','CRRA','dP','dPA']
for page,model in [(19,'RoBERTa'),(20,'distilRoBERTa'),(21,'BERT'),(22,'distilBERT')]:
    rows=[]
    for line in Path(f'tmp/pdfs/page-{page:02d}.txt').read_text().splitlines():
        m=re.match(r'"'^(Religion|Nationality|Race|Socioeconomic|Disability|Physical Appearance|Gender|Sexual Orientation|Age)'"\\s+(.+)"'$'"',line)
        if m:
            vals=[float(x) for x in re.findall(r'\\d+(?:\\.\\d+)?',m.group(2))]
            if len(vals)==7: rows.append((m.group(1),vals))
    print(model, 'category rows:',len(rows))
    for direction,subset in [('dis',rows[:9]),('adv',rows[9:])]:
        failures={name:[cat for cat,vals in subset if (vals[j]<50 if direction=='dis' else vals[j]>50)] for j,name in enumerate(metrics)}
        ties={name:[cat for cat,vals in subset if vals[j]==50] for j,name in enumerate(metrics)}
        print(direction, 'wrong-direction counts:',{k:len(v) for k,v in failures.items()},'ties:',{k:v for k,v in ties.items() if v})
PY"
